+/// Scan Python source `text`, which starts inside a triple-quoted string of
+/// the quote character `open` when that is `Some`. Returns the quote character
+/// of the triple-quoted string still open at the end of `text`, and whether a
+/// `#` comment starts outside every string in `text`.
+fn python_scan(text: &str, open: Option<char>) -> (Option<char>, bool) {
+    let mut open = open;
+    let mut comment = false;
+    let mut chars = text.char_indices();
+    while let Some((index, c)) = chars.next() {
+        let rest = &text[index..];
+        let tripled = rest.chars().take(3).filter(|&next| next == c).count() == 3;
+        if let Some(quote) = open {
+            if c == '\\' {
+                chars.next();
+            } else if c == quote && tripled {
+                chars.next();
+                chars.next();
+                open = None;
+            }
+        } else if c == '#' {
+            comment = true;
+            for (_, next) in chars.by_ref() {
+                if next == '\n' {
+                    break;
+                }
+            }
+        } else if c == '"' || c == '\'' {
+            if tripled {
+                chars.next();
+                chars.next();
+                open = Some(c);
+            } else {
+                while let Some((_, next)) = chars.next() {
+                    if next == '\\' {
+                        chars.next();
+                    } else if next == c || next == '\n' {
+                        break;
+                    }
+                }
+            }
+        }
+    }
+    (open, comment)
+}
